Profe, el proyecto final es un sistema de biblioteca. Tengo que modelar un libro con isbn, título, autor y si está disponible. Empecé así:

```c
struct Libro {
    int isbn;
    char titulo[100];
    char autor[50];
    int disponible;
};
```

¿Está bien?

```c
#include <stdbool.h>

struct Libro {
    int isbn;
    char titulo[100];
    char autor[50];
    bool disponible;
};
```

Exactoo. Con `bool` la condición se lee casi como inglés: "si el libro está disponible". No necesitas `== true` ni `== 1` — el valor bool ya es la condición. Mira el sistema completo:

```c
#include <stdio.h>
#include <stdbool.h>
#include <string.h>

#define MAX_LIBROS 6

typedef struct {
    int  isbn;
    char titulo[100];
    char autor[50];
    bool disponible;
} Libro;

void listarDisponibles(Libro catalogo[], int n) {
    printf("\n=== Libros disponibles ===\n");
    int contador = 0;
    for (int i = 0; i < n; i++) {
        if (catalogo[i].disponible) {
            printf("ISBN: %d | %s — %s\n",
                   catalogo[i].isbn,
                   catalogo[i].titulo,
                   catalogo[i].autor);
            contador++;
        }
    }
    if (contador == 0) {
        printf("No hay libros disponibles en este momento.\n");
    } else {
        printf("Total disponibles: %d\n", contador);
    }
}

int main() {
    Libro catalogo[MAX_LIBROS] = {
        {1001, "El Principito",              "Antoine de Saint-Exupéry", true},
        {1002, "Cien años de soledad",       "Gabriel García Márquez",  false},
        {1003, "1984",                        "George Orwell",           true},
        {1004, "Don Quijote de la Mancha",   "Miguel de Cervantes",     false},
        {1005, "Rayuela",                     "Julio Cortázar",          true},
        {1006, "La casa de los espíritus",   "Isabel Allende",          true}
    };

    listarDisponibles(catalogo, MAX_LIBROS);

    /* Simular préstamo del libro 1001 */
    catalogo[0].disponible = false;
    printf("\n[El Principito ha sido prestado]\n");

    listarDisponibles(catalogo, MAX_LIBROS);

    return 0;
}
```

Nota que también usamos `typedef` para que las declaraciones sean `Libro` en lugar de `struct Libro`. ¿Qué hace `catalogo[0].disponible = false;`?
